 static final String P=SourceProc68FirstQueueMethods.P,N=SourceProc68FirstQueueMethods.N,C=SourceProc68FirstQueueMethods.C,L=SourceProc68FirstQueueMethods.L;static void need(boolean b,String s){if(!b)throw new AssertionError(s);}static void load(MethodNode m,MethodInsnNode call,int slot){var p=FreezeAcceptedMethods.prev(call);need(p instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==slot,"exact first metadata operand "+slot);m.instructions.remove(p);}static void back(MethodNode m,int first,MethodNode old){for(var node:m.instructions){if(node instanceof VarInsnNode v&&v.var>=first)v.var--;if(node instanceof IincInsnNode v&&v.var>=first)v.var--;}m.desc=old.desc;m.maxLocals=old.maxLocals;}
